package com.cloudticket.comment.persistence.entity;
import com.baomidou.mybatisplus.annotation.IdType; import com.baomidou.mybatisplus.annotation.TableId; import com.baomidou.mybatisplus.annotation.TableName; import java.time.Instant;
@TableName("comment") public class CommentEntity { @TableId(value="id",type=IdType.INPUT) private String id; private String activityId; private String userId; private String parentId; private String content; private String status; private Integer likeCount; private Integer replyCount; private Instant createdAt; private Instant updatedAt;
 public String getId(){return id;} public void setId(String v){id=v;} public String getActivityId(){return activityId;} public void setActivityId(String v){activityId=v;} public String getUserId(){return userId;} public void setUserId(String v){userId=v;} public String getParentId(){return parentId;} public void setParentId(String v){parentId=v;} public String getContent(){return content;} public void setContent(String v){content=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public Integer getLikeCount(){return likeCount;} public void setLikeCount(Integer v){likeCount=v;} public Integer getReplyCount(){return replyCount;} public void setReplyCount(Integer v){replyCount=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} public Instant getUpdatedAt(){return updatedAt;} public void setUpdatedAt(Instant v){updatedAt=v;} }
